import {
  LOGIN_HTTP_ERROR,
  LOGIN_USERNAME_CHANGE,
  LOGIN_PASSWORD_CHANGE
} from '../actions/loginActions';


export default function loginReducer(state, action) {
  
  switch(action.type) {

    case LOGIN_HTTP_ERROR:
      
      return {
        ...state,
        authErrorMessage: action.error  
      };

    case LOGIN_USERNAME_CHANGE:
        console.log('login username change');
      return {
        
        ...state,
        scUsername: action.scUsername
      };
    
    case LOGIN_PASSWORD_CHANGE:
    console.log('login password change');
      return {
        ...state,
        scPassword: action.scPassword
      };
    
      
    default:
      // ALWAYS have a default case in a reducer
      return state;
  }
}
